application.css:
* { box-sizing: border-box; }
:root { font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #172033; background: #eef2ff; }
body { margin: 0; min-width: 320px; background: radial-gradient(circle at 10% 0%, #dce8ff 0, transparent 35%), linear-gradient(135deg, #f7f9ff 0%, #eef2ff 100%); }
.page-shell { min-height: 100vh; padding: 48px 18px; display: flex; justify-content: center; align-items: flex-start; }
.quiz-card { width: min(760px, 100%); background: rgba(255,255,255,.94); border: 1px solid #e0e7f5; border-radius: 24px; box-shadow: 0 22px 60px rgba(43, 62, 115, .14); overflow: hidden; }
.quiz-header { padding: 42px 46px 30px; background: linear-gradient(120deg, #263a82, #526bd7); color: white; }
.eyebrow { margin: 0 0 10px; color: #c9d5ff; font-size: .76rem; font-weight: 800; letter-spacing: .13em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(2rem, 5vw, 3rem); letter-spacing: -.04em; }
.intro { margin: 12px 0 0; color: #e1e7ff; font-size: 1rem; }
#quiz-form { padding: 8px 46px 28px; }
.question { border: 0; border-bottom: 1px solid #e6eaf3; margin: 0; padding: 28px 0; }
.question legend { width: 100%; padding: 0; font-size: 1.08rem; font-weight: 750; line-height: 1.45; }
.question-number { display: inline-grid; place-items: center; width: 31px; height: 31px; margin-right: 10px; border-radius: 9px; background: #edf1ff; color: #526bd7; font-size: .75rem; vertical-align: middle; }
.options { display: grid; gap: 10px; margin-top: 17px; }
.option { display: flex; align-items: center; gap: 12px; padding: 13px 15px; border: 1px solid #dfe4ef; border-radius: 11px; cursor: pointer; color: #4c5870; transition: .18s ease; }
.option:hover { border-color: #91a4ed; background: #f7f8ff; transform: translateY(-1px); }
.option:has(input:checked) { border-color: #526bd7; background: #f0f3ff; color: #263a82; font-weight: 650; box-shadow: 0 0 0 2px rgba(82,107,215,.1); }
.option input { position: absolute; opacity: 0; pointer-events: none; }
.custom-radio { width: 18px; height: 18px; border: 2px solid #b8c1d4; border-radius: 50%; position: relative; flex: 0 0 auto; }
.option input:checked + .custom-radio { border-color: #526bd7; }
.option input:checked + .custom-radio::after { content: ""; position: absolute; inset: 3px; background: #526bd7; border-radius: 50%; }
.quiz-footer { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding-top: 25px; }
.hint { margin: 0; color: #7b8598; font-size: .88rem; }
button { border: 0; border-radius: 10px; padding: 14px 21px; background: #526bd7; color: white; font: inherit; font-weight: 750; cursor: pointer; box-shadow: 0 8px 18px rgba(82,107,215,.25); transition: .2s ease; }
button:hover { background: #4059c3; transform: translateY(-2px); }
button span { margin-left: 8px; font-size: 1.15em; }
.score-panel { margin: 0 46px 42px; padding: 24px; border-radius: 16px; background: #f7f8fc; text-align: center; }
.score-label { margin: 0 0 3px; color: #798399; font-size: .78rem; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }
.score { color: #263a82; font-size: 3rem; font-weight: 850; line-height: 1.15; }
.score span { color: #9aa4b8; font-size: 1.1rem; font-weight: 600; }
.score-message { margin: 5px 0 0; color: #6c768b; }
@media (max-width: 560px) { .page-shell { padding: 18px 10px; } .quiz-header { padding: 30px 24px 25px; } #quiz-form { padding: 5px 24px 25px; } .score-panel { margin: 0 24px 28px; } .quiz-footer { align-items: flex-start; flex-direction: column; } button { width: 100%; } }

application.javascript:
const form = document.getElementById('quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const hint = document.getElementById('hint');
const message = document.getElementById('score-message');
const answers = { q1: 'mars', q2: 'pacific', q3: 'six' };

form.addEventListener('submit', function (event) {
  event.preventDefault();
  const formData = new FormData(form);
  const names = Object.keys(answers);
  const unanswered = names.filter((name) => !formData.get(name));

  if (unanswered.length) {
    hint.textContent = `Please answer ${unanswered.length === 1 ? 'the remaining question' : 'all remaining questions'} first.`;
    hint.classList.add('error');
    const firstMissing = form.querySelector(`input[name="${unanswered[0]}"]`);
    if (firstMissing) firstMissing.closest('.question').scrollIntoView({ behavior: 'smooth', block: 'center' });
    return;
  }

  let score = 0;
  names.forEach((name) => { if (formData.get(name) === answers[name]) score += 1; });
  scoreElement.textContent = `${score}`;
  const suffix = document.createElement('span');
  suffix.textContent = ' / 3';
  scoreElement.appendChild(suffix);
  scoreElement.dataset.score = String(score);
  hint.textContent = 'Your answers have been scored.';
  hint.classList.remove('error');
  message.textContent = score === 3 ? 'Perfect score — excellent work!' : score === 0 ? 'Keep learning and try again.' : 'Nice effort — there is always more to discover.';
});
